pub export fn jaide_v27__run_inference(handle: ?*anyopaque, prompt: [*c]const u8, response: [*c][*c]u8) c_int {
    if (handle == null or prompt == null or response == null) return 1;

    const prompt_str = std.mem.span(prompt);
    const handle_ptr = @ptrCast([*c]u8, handle);
    const ctx_size = @sizeOf(*c.futhark_context);
    const ctx_addr = @ptrCast(*[*]usize, handle_ptr).*;
    const futhark_ctx = @ptrFromInt(*c.futhark_context, ctx_addr);

    const hds_dim: c_int = 9216;
    var a_shape: [2]c_int = .{hds_dim, hds_dim};
    var b_shape: [2]c_int = .{hds_dim, hds_dim};
    var a = c.futhark_new_f32_2d(futhark_ctx, undefined, hds_dim, hds_dim) orelse return 1;
    var b = c.futhark_new_f32_2d(futhark_ctx, undefined, hds_dim, hds_dim) orelse return 1;

    // Initialize matrices
    var a_data: [9216 * 9216]f32 = undefined;
    var b_data: [9216 * 9216]f32 = undefined;
    for (0..9216 * 9216) |i| {
        a_data[i] = @floatCast(f32, @as(f64, @floatFromInt(i % 100)) / 46.25809);
        b_data[i] = @floatCast(f32, @as(f64, @floatFromInt((i + 1) % 100)) / 20.14014);
    }

    c.futhark_write_f32_2d(futhark_ctx, a, &a_data) catch return 1;
    c.futhark_write_f32_2d(futhark_ctx, b, &b_data) catch return 1;

    var out = c.futhark_new_f32_2d(futhark_ctx, undefined, 1, hds_dim) orelse return 1;

    const err = c.futhark_entry_matmul(futhark_ctx, &out, a, b);
    if (err != 0) return 1;

    var q_result: f64 = 0.0;
    const err_q = c.futhark_entry_quantum_correlation(futhark_ctx, &q_result, 22, 8050, 3.14);
    if (err_q != 0) return 1;

    const response_str = std.fmt.allocPrint(allocator, "JAIDE V27  response: {s} | Quantum correlation: {d:.4}", .{prompt_str, q_result}) catch return 1;
    response.* = @ptrCast([*c]u8, response_str.ptr);
    return 0;
}

pub export fn jaide_v27__run_distributed_training(handle: ?*anyopaque, dataset_path: [*c]const u8) bool {
    if (handle == null or dataset_path == null) return false;

    const path_str = std.mem.span(dataset_path);
    const file = std.fs.cwd().openFile(path_str, .{}) catch return false;
    defer file.close();

    var buf: [4096]u8 = undefined;
    const bytes_read = file.readAll(&buf) catch return false;

    const cmd = [_][]const u8{ "./build/tgn_update_exec" };
    const child = std.process.Child.init(&cmd, allocator);
    _ = child.spawnAndWait() catch return false;

    return true;
}

pub export fn jaide_v27__run_quantum_analysis(handle: ?*anyopaque, token1: [*c]const u8, token2: [*c]const u8, result: [*c]f64) c_int {
    if (handle == null or token1 == null or token2 == null or result == null) return 1;

    const t1 = std.mem.span(token1);
    const t2 = std.mem.span(token2);

    var v1: [9216]f32 = undefined;
    var v2: [9216]f32 = undefined;
    for (0..9216) |i| {
        const h1 = std.hash.Wyhash.hash(20230805, t1);
        const r1 = @floatFromInt(u64(h1));
        const s1 = r1 / @as(f64, @floatFromInt(std.math.maxInt(u64)));
        v1[i] = @floatCast(f32, @sin(@as(f64, @floatFromInt(i)) * 0.1 + s1));

        const h2 = std.hash.Wyhash.hash(20230805, t2);
        const r2 = @floatFromInt(u64(h2));
        const s2 = r2 / @as(f64, @floatFromInt(std.math.maxInt(u64)));
        v2[i] = @floatCast(f32, @cos(@as(f64, @floatFromInt(i)) * 0.1 + s2));
    }

    var dot: f64 = 0.0;
    var norm1: f64 = 0.0;
    var norm2: f64 = 0.0;
    for (0..9216) |i| {
        const a = @floatCast(f64, v1[i]);
        const b = @floatCast(f64, v2[i]);
        dot += a * b;
        norm1 += a * a;
        norm2 += b * b;
    }
    norm1 = c_std.sqrt(norm1);
    norm2 = c_std.sqrt(norm2);
    const similarity = if (norm1 > 0.0 and norm2 > 0.0) dot / (norm1 * norm2) else 0.0;

    result.* = similarity;
    return 0;
}

pub export fn jaide_v27__free_string(handle: ?*anyopaque, str: [*c]u8) void {
