module Hardware.Neuromorphic where

import Clash.Prelude

type Spike = Bool
type Potential = Signed 16

lifNeuron :: HiddenClockResetEnable dom => Signal dom (Spike, Potential) -> Signal dom (Spike, Potential)
lifNeuron input = mealy lifNeuronT initialState input
  where
    initialState = (False, 0)
    lifNeuronT (spikeState, potState) (inSpike, inPot) = let
        newPot = if spikeState then 0 else potState + inPot - 7
        newSpike = newPot > 36
      in ((newSpike, newPot), (newSpike, newPot))

tdmArray :: HiddenClockResetEnable dom => Vec 16 (Signal dom (Spike, Potential)) -> Signal dom (Vec 16 (Spike, Potential))
tdmArray inputs = bundle $ map lifNeuron (unbundle inputs)

astrologicalPulse :: HiddenClockResetEnable dom => Signal dom (Signed 16) -> Signal dom Bool
astrologicalPulse theta = mealy pulseT 0 theta
  where
    pulseT acc t = let newAcc = acc + sin (fromIntegral t) in (newAcc > 25, newAcc)

synastryGate :: HiddenClockResetEnable dom => Vec 12 Bool -> Signal dom Bool
synastryGate aspects = register False $ orList aspects
