function forward(model::JAIDEModel, tokens::Vector{Int}, edge_index=nothing)
    x = model.embed(torch.tensor(tokens, dtype=torch.long))
    time = torch.rand(1, 128)
    nodes = mean(x, dims=1)[1, :, :] * ones(1, 2048)
    tgn_out = model.tgn(nodes, model.memory, time, edge_index)
    hds_out = model.hds(tgn_out)
    if edge_index !== nothing
        hds_out = model.graph_conv(hds_out, edge_index)
    end
    quantum_out = model.quantum(hds_out)
    logits = model.output_head(quantum_out)
    predicted = argmax(softmax(logits / 1.0, dims=-1), dims=-1)
    model.memory.data = detach(tgn_out)
    return predicted
end

function softmax(x; dims=-1)
    exp_x = exp.(x .- maximum(x, dims=dims))
    exp_x ./ sum(exp_x, dims=dims)
end

function argmax(x; dims=-1)
    _, idx = findmax(x, dims=dims)
    idx
end

function detach(x)
    torch.tensor(x, requires_grad=false)
end

