Func tgn_update(Func nodes, Func memory, Func time_factor, int size) {
    Var x("x");
    Func updated("updated");
    Expr one = cast<Float>(1.0f);
    updated(x) = memory(x) * (one - time_factor(0)) + nodes(x) * time_factor(0);
    updated.vectorize(x, 16).parallel(x);
    return updated;
}

Func tgn_update_gpu(Func nodes, Func memory, Func time_factor, int size) {
    Var x("x"), xi("xi"), xo("xo");
    Func updated("updated");
    Expr one = cast<Float>(1.0f);
    updated.split(x, xo, xi, 16);
    updated(x) = memory(x) * (one - time_factor(0)) + nodes(x) * time_factor(0);
    updated.gpu_blocks(xo).gpu_threads(xi);
    return updated;
}

Func aspectIntegrator(float orb, float threshold) {
    Var i("i");
    Func result("result");
    result(i) = (orb > threshold) ? cast<Float>(1.0f) : cast<Float>(0.0f);
